function adapt(input, solve, kit) {
  const [n, starts] = input, start = Date.now(), prints = [];
  const fooBar = new solve(n);
  for (const name of ['foo', 'bar']) if (!fooBar || typeof fooBar[name] !== 'function') throw new Error(`FooBar needs a method ${name}.`);
  const printer = (word) => () => {
    prints.push({ text: word, t: Date.now() - start });
    kit.trace(`"${word}" is printed`);
  };
  setTimeout(() => {
    kit.trace('Thread A starts and calls foo()');
    fooBar.foo(printer('foo'));
  }, starts[0]);
  setTimeout(() => {
    kit.trace('Thread B starts and calls bar()');
    fooBar.bar(printer('bar'));
  }, starts[1]);
  // A correct solution has printed everything by the later start; the extra time shows late prints.
  return new Promise((resolve) => setTimeout(() => resolve({
    output: prints.map((p) => p.text).join(''),
    times: prints.map((p) => p.t),
  }), Math.max(...starts) + 50));
}

