class FooBar {
  constructor(n) {
    this.n = n;
    this.turn = 0;
    this.parked = [null, null];
  }

  // Side 0 is foo and side 1 is bar; an even turn belongs to foo.
  wait(side) {
    if (this.turn % 2 === side) return Promise.resolve();
    return new Promise((resolve) => { this.parked[side] = resolve; });
  }

  pass() {
    this.turn += 1;
    const wake = this.parked[this.turn % 2];
    this.parked[this.turn % 2] = null;
    if (wake) wake();
  }

  async foo(printFoo) {
    for (let i = 0; i < this.n; i++) { await this.wait(0); printFoo(); this.pass(); }
  }

  async bar(printBar) {
    for (let i = 0; i < this.n; i++) { await this.wait(1); printBar(); this.pass(); }
  }
}

