function generate(rand, size) {
  const pick = (n) => Math.floor(rand() * n);
  const n = size === 'small' ? 1 + pick(5) : 500 + pick(501);
  const top = size === 'small' ? 30 : 1000, roll = rand();
  const same = pick(top + 1);
  const starts = roll < 0.25 ? [same, same] : [pick(top + 1), pick(top + 1)];
  return [n, starts];
}
